const offlineMessage=(type,id)=>new Promise(async(resolve,reject)=>{try{const reg=await navigator.serviceWorker.ready,w=navigator.serviceWorker.controller||reg.active;if(!w)throw Error('Reload the dashboard once to enable offline saving');const ch=new MessageChannel(),timer=setTimeout(()=>reject(Error('Offline save timed out')),30000);ch.port1.onmessage=e=>{clearTimeout(timer);e.data&&e.data.ok?resolve(e.data):reject(Error(e.data?.error||'Offline save failed'))};w.postMessage({type,url:'/api/dl/'+encodeURIComponent(id)},[ch.port2])}catch(e){reject(e)}});
