/* GALLERY: shared class photos (JPEG, shrunk in the browser). Anyone can add; owners and admins can delete. */
const shrinkB=(f,m,cb)=>{const r=new FileReader();r.onload=()=>{const i=new Image();i.onload=()=>{const k=Math.min(1,m/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=Math.round(i.width*k);c.height=Math.round(i.height*k);c.getContext('2d').drawImage(i,0,0,c.width,c.height);c.toBlob(b=>cb(b),'image/jpeg',.76)};i.onerror=()=>{toast('NOT AN IMAGE');cb(null)};i.src=r.result};r.onerror=()=>cb(null);r.readAsDataURL(f)};
