V.gallery=()=>{const q=Q(),all=gl(),als=[...new Set(all.map(g=>g.al))].sort(),ad=q.role==='admin';if(st.ga&&!als.includes(st.ga))st.ga='';
 const l=all.filter(g=>!st.ga||g.al===st.ga),cur=st.gv&&l.find(g=>g.id===st.gv),ix=cur?l.indexOf(cur):-1,pv=ix>0?l[ix-1]:null,nx=ix>=0&&ix<l.length-1?l[ix+1]:null;
 return H('Gallery','Lab sessions, tours and campus memories. Anyone in the batch can add photos; you can delete your own'+(ad?', and admins can delete any.':'.'))+
 '<div class="schedule-card"><span class="tag">Add photos</span><form data-x="gal" class="fr"><label class="fl">Photos (up to 6)<input class="in" name="f" type="file" accept="image/*" multiple required></label><label class="fl">Caption (optional)<input class="in" name="cap" maxlength="140"></label><label class="fl">Album<input class="in" name="al" list="gal-al" maxlength="30" value="'+esc(st.ga||'General')+'" required></label><datalist id="gal-al">'+[...new Set(['General','Lab','Tour','Events','Campus'].concat(als))].map(x=>'<option value="'+esc(x)+'">').join('')+'</datalist><button class="btn p">Upload</button></form></div>'+ 
 '<div class="schedule-card">'+T('ga',[['','All ('+all.length+')']].concat(als.map(x=>[x,esc(x)+' ('+all.filter(g=>g.al===x).length+')'])))+(l.length?'<div class="gx">'+l.map(g=>'<button class="gi" data-a="x_gv" data-id="'+g.id+'" aria-label="Open photo'+(g.cap?': '+esc(g.cap):'')+'"><img loading="lazy" decoding="async" alt="'+esc(g.cap||'Class photo')+'" src="/api/photo/'+g.id+'/thumb">'+(g.cap?'<span>'+esc(g.cap)+'</span>':'')+'</button>').join('')+'</div>':E('No photos yet. Add the first one.'))+'</div>'+ 
 (cur?'<div class="glb" data-a="x_gv" data-id="" role="dialog" aria-label="Photo viewer"><div class="gbox" data-a="x_noop"><img decoding="async" alt="'+esc(cur.cap||'Class photo')+'" src="/api/photo/'+cur.id+'"><div class="gm"><b>'+esc(cur.cap||'Untitled')+'</b><span>'+esc(cur.al)+' · '+esc(cur.by)+' · '+when(cur.ts)+'</span></div><div class="gm">'+(pv?'<button class="mini" data-a="x_gv" data-id="'+pv.id+'">‹ Prev</button>':'')+'<button class="mini" data-a="x_gv" data-id="">Close</button>'+(nx?'<button class="mini" data-a="x_gv" data-id="'+nx.id+'">Next ›</button>':'')+((cur.mine||ad)?'<button class="mini" data-a="z_gdel" data-id="'+cur.id+'">Delete</button>':'')+'</div></div></div>':'')};
document.addEventListener('keydown',e=>{if(dv.hidden||d.tab!=='gallery'||!st.gv||/INPUT|TEXTAREA|SELECT/.test((document.activeElement||{}).tagName||''))return;const l=gl().filter(g=>!st.ga||g.al===st.ga),i=l.findIndex(g=>g.id===st.gv);if(e.key==='Escape')st.gv='';else if(e.key==='ArrowLeft'&&i>0)st.gv=l[i-1].id;else if(e.key==='ArrowRight'&&i>=0&&i<l.length-1)st.gv=l[i+1].id;else return;d.render()});

