dv.addEventListener('change',async e=>{const input=e.target.closest('[data-push-pref]');if(!input)return;const key=input.dataset.pushPref,prev=pushPrefs[key];pushPrefs[key]=input.checked;try{const p=await optionalCall('PUT','/push/preferences',pushPrefs);if(!p){prefsAvailable=false;prefsLoaded=true;d.render();return}pushPrefs={...pushPrefs,...p};prefsLoaded=true;toast('NOTIFICATION PREFERENCE SAVED')}catch(err){pushPrefs[key]=prev;d.render()}});
