async function enablePush(){
 if(!isSecureContext){toast('PUSH NOTIFICATIONS REQUIRE HTTPS');return}
 if(!('Notification'in window)||!('PushManager'in window)||!('serviceWorker'in navigator)){toast('OPEN THIS SITE IN A BROWSER THAT SUPPORTS PUSH');return}
 let permission=Notification.permission;
 if(permission==='default')try{permission=await Notification.requestPermission()}catch(e){}
 if(permission!=='granted'){toast('ALLOW NOTIFICATIONS IN YOUR BROWSER SETTINGS');return}
 try{
  const reg=await navigator.serviceWorker.ready,key=(await call('GET','/push/key')).key;
  let sub=await reg.pushManager.getSubscription();
  if(sub?.options?.applicationServerKey){let raw=key.replace(/-/g,'+').replace(/_/g,'/');raw+='='.repeat((4-raw.length%4)%4);const expected=Uint8Array.from(atob(raw),c=>c.charCodeAt(0)),actual=new Uint8Array(sub.options.applicationServerKey);if(expected.length!==actual.length||expected.some((v,i)=>v!==actual[i])){await sub.unsubscribe();sub=null}}
  if(!sub){let raw=key.replace(/-/g,'+').replace(/_/g,'/');raw+='='.repeat((4-raw.length%4)%4);sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(atob(raw),c=>c.charCodeAt(0))})}
  await call('POST','/push/subscribe',sub.toJSON());toast('PUSH ALERTS ENABLED');
 }catch(e){toast(e.message||'COULD NOT ENABLE PUSH ALERTS')}
}
