 b.textContent=n>9?'9+':n;b.hidden=!n;$('#bell').classList.toggle('has-unread',n>0);$('#bell').setAttribute('aria-label',n?n+' unread alerts':'Alerts');$('#bell').title=n?n+' unread alerts':'Alerts';h.style.backgroundImage=p?'url('+p+')':'';h.textContent=p?'':ini;loadPushPrefs();
 if(np&&!np.hidden){np.style.backgroundImage=p?'url('+p+')':'';np.textContent=p?'':ini}
